mapper.select:
SELECT id, user_id, title, completed, completed_at, created_at, updated_at
FROM task
WHERE id = #{id} AND user_id = #{userId}

mapper.update:
UPDATE task
SET title = #{title},
    completed = #{completed},
    completed_at = #{completedAt,jdbcType=TIMESTAMP}
WHERE id = #{id} AND user_id = #{userId}
